```python
def knapsack(items: list[tuple[int, int]], capacity: int) -> int:
    # Separate items with weight 0 since they can always be taken
    base_value = 0
    filtered_items = []
    for weight, value in items:
        if weight == 0:
            base_value += value
        elif weight <= capacity:
            filtered_items.append((weight, value))

    # Standard 1D DP array for 0/1 Knapsack
    dp = [0] * (capacity + 1)

    for weight, value in filtered_items:
        for w in range(capacity, weight - 1, -1):
            if dp[w - weight] + value > dp[w]:
                dp[w] = dp[w - weight] + value

    return dp[capacity] + base_value
```
